-- =====================================================================
-- Web sitesi: ürünler (admin panelinden yönetilir)
--
-- Gövde metni (body) sade biçimdedir: boş satırla ayrılan paragraflar,
-- "## " ile başlayan satırlar ara başlık, "> " ile başlayanlar alıntı.
-- Öne çıkanlar (highlights) her satırda bir madde.
-- Başlangıç içeriği eski mbdentaire.com ürün sayfalarından alınmıştır.
-- =====================================================================

create table cms_products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 60),
  category text not null default 'sabit' check (category in ('sabit', 'hareketli', 'ortodonti', 'dijital')),
  name jsonb not null default '{}'::jsonb check (is_i18n_text(name)),
  summary jsonb not null default '{}'::jsonb check (is_i18n_text(summary)),
  body jsonb not null default '{}'::jsonb check (is_i18n_text(body)),
  highlights jsonb not null default '{}'::jsonb check (is_i18n_text(highlights)),
  seo_title jsonb not null default '{}'::jsonb check (is_i18n_text(seo_title)),
  seo_description jsonb not null default '{}'::jsonb check (is_i18n_text(seo_description)),
  image_path text,
  gallery text[] not null default '{}',
  sort integer not null default 0,
  is_active boolean not null default true,
  deleted_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  updated_by uuid default auth.uid()
);
create index on cms_products (category, sort) where deleted_at is null;

create trigger cms_products_touch before update on cms_products for each row execute function cms_touch();
create trigger audit_cms_products after insert or update or delete on cms_products for each row execute function audit_trigger();

alter table cms_products enable row level security;
create policy cms_products_public_read on cms_products for select to anon, authenticated
  using (deleted_at is null and is_active);
create policy cms_products_editor_all on cms_products for all to authenticated
  using (can_manage_site()) with check (can_manage_site());
grant select on cms_products to anon;
grant select, insert, update, delete on cms_products to authenticated;

-- Çöp kutusu temizliği ürünleri de kapsasın
create or replace function cms_purge_trash()
returns integer language plpgsql security definer set search_path = public as $$
declare n integer := 0; c integer;
begin
  delete from cms_slides where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_announcements where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  delete from cms_products where deleted_at < now() - interval '30 days';
  get diagnostics c = row_count; n := n + c;
  return n;
end $$;
revoke execute on function cms_purge_trash() from public, anon, authenticated;

-- ---------------------------------------------------------------------
-- Başlangıç içeriği (eski siteden; TR / EN / FR)
-- ---------------------------------------------------------------------
insert into cms_products (slug, category, name, summary, body, highlights, sort) values
  ('zirkonyum', 'sabit', '{"tr": "Zirkonyum", "en": "Zirconia", "fr": "Zircone"}'::jsonb, '{"tr": "Full anatomik ya da altyapı, çok katmanlı bloklar", "en": "Full-contour or framework, multilayer blocks", "fr": "Monolithique ou armature, blocs multicouches"}'::jsonb, '{"tr": "## Detayları ortaya çıkaran kusursuz üretim\n\nTamamen dijital ortamda tasarlanıp, bilgisayar destekli sistemlerde üretilen zirkon protezler hem fonksiyonel hem de biyolojik anlamda kullanıcılara mükemmel uyum sağlamaktadır. Mükemmel uyuma ek olarak estetik anlamda da en iyi sonuca ulaşmak için zirkon protezler hem hekimler hem de kullanıcılar tarafından tercih edilir olmuştur. Porselen kaplamalı protezler için altyapı olarak kullanılan zirkon malzemeler estetik açıdan çok daha iyi sonuçlar verdiği için uzun yıllardır metal altyapılı protezlerin en önemli alternatifidir.\n\n## Full anatomik uyum\n\nYüksek mukavemet ve şeffaflığa sahip çok katmanlı blokların da gelişimi ile birlikte full anatomik zirkon kron ve köprüler en önemli sabit protez alternatiflerinden birdir. Estetik olarak her geçen gün daha iyiye giden zirkon malzemeler, paralelinde mukavemet değerlerini de artırarak daha fazla tercih edilen ürünler ortaya çıkarmaya başlamıştır.\n\n> \"MB Dental bünyesine kattığı son teknoloji makinalar ile sahip olduğu makine parkurunu günden güne genişletmektedir. Güçlü 3 boyutlu tasarım ekibinin elinden çıkan detaylı tasarımları bu makinalar ile en ince ayrıntısına kadar kusursuz bir şekilde üretmektedir. Gerek zirkon altyapılar, gerek full anatomik tasarımlar olsun MB Dental tüm detayları CAD/CAM aşamasında ortaya çıkararak, form ve adaptasyon anlamında ikincil müdahaleleri minimize etmektedir. MB Dental bu süreci en kaliteli ürüne en hızlı şekilde ulaşmanın tek yolu olarak görmektedir.\"", "en": "## Flawless production that brings out the details\n\nZirconia prostheses, which are completely designed in a digital environment and produced in computer-aided systems, provide perfect harmony to the users in both functional and biological terms. In addition to the perfect fit, zirconia prostheses have become preferred by both physicians and users in order to achieve the best aesthetic result. Zirconia materials, which are used as a substructure for porcelain-coated prostheses, have been the most important alternative to metal-based prostheses for many years, as they provide much better aesthetic results.\n\n## Full anatomical fit\n\nWith the development of multilayer blocks with high strength and transparency, full anatomical zirconia crowns and bridges are one of the most important fixed prosthesis alternatives. Zirconia materials, which are getting better every day in terms of aesthetics, have started to create more preferred products by increasing their strength values in parallel.\n\n> \"MB Dental is expanding its machine park day by day with the latest technology machines it has acquired. With these machines, MB Dental produces the detailed designs created by its strong 3D design team flawlessly down to the finest detail. Whether zirconia substructures or full anatomical designs, MB Dental reveals all the details at the CAD/CAM stage, minimizing secondary interventions in terms of form and adaptation. MB Dental sees this process as the only way to achieve the highest quality product in the fastest way.\"", "fr": "## Une production sans faille qui révèle les détails\n\nLes prothèses en zircone, qui sont entièrement conçues dans un environnement numérique et produites par des systèmes assistés par ordinateur, offrent une harmonie parfaite aux utilisateurs, tant sur le plan fonctionnel que biologique. Outre l''harmonie parfaite, les prothèses en zircone ont été préférées par les médecins et les utilisateurs afin d''obtenir le meilleur résultat esthétique. Les matériaux en zircone, qui sont utilisés comme sous-structure pour les prothèses revêtues de porcelaine, sont depuis de nombreuses années l''alternative la plus importante aux prothèses à base de métal, car ils donnent de bien meilleurs résultats en termes d''esthétique.\n\n## Ajustement anatomique complet\n\nAvec le développement de blocs multicouches très résistants et transparents, les couronnes et les bridges en zircone entièrement anatomiques constituent l''une des principales alternatives aux prothèses fixes. Les matériaux en zircone, qui s''améliorent chaque jour en termes d''esthétique, ont commencé à créer des produits plus appréciés en augmentant parallèlement leurs valeurs de résistance.\n\n> « MB Dental agrandit son parc de machines jour après jour avec des machines de dernière technologie. Grâce à ces machines, MB Dental produit les dessins détaillés créés par sa solide équipe de conception 3D de manière irréprochable dans les moindres détails. Qu''il s''agisse de sous-structures en zircone ou de conceptions anatomiques complètes, MB Dental minimise les interventions secondaires en termes de forme et d''adaptation en révélant tous les détails au stade de la CAO/FAO. MB Dental considère ce processus comme le seul moyen d''obtenir le plus rapidement possible un produit de la plus haute qualité. »"}'::jsonb, '{}'::jsonb, 10),
  ('porselen', 'sabit', '{"tr": "Porselen", "en": "Porcelain", "fr": "Céramo-métallique"}'::jsonb, '{"tr": "Metal destekli, el işçiliği tabakalama", "en": "Porcelain-fused-to-metal, hand layered", "fr": "Stratification à la main"}'::jsonb, '{"tr": "## Yetenek ve tecrübenin buluşma noktası\n\nTeknolojinin hızlı gelişimi birçok yeni malzeme ve indikasyonun ortaya çıkmasını sağlıyor. Tüm bu gelişmelere rağmen porselen kaplamalı protezler ile elde edilen estetik ve fonksiyon seviyesine herhangi bir malzeme ulaşmış değil. Emek yoğun bir proses ile üretilen porselen kaplamalı protezler, teknolojinin üretimde payının her geçen gün arttığı bu dönemde, vazgeçilmez estetik özellikleri ile yerini korumayı başarıyor.\n\nKaliteli porselen uygulamalarında uzun yıllar boyunca sayısız vaka üzerinde çalışıp adım adım kendini geliştiren ve tecrübe kazanan diş teknisyenlerinin payı göz ardı edilemez. MB Dental her süreç adımında ustalaşmış, tüm müşteri beklentilerini eksiksiz karşılayabilecek nitelikte, alanında tecrübeli teknisyenleriyle fonksiyonunu kaybetmeden en yüksek estetiğe ulaşan protezler üretmektedir.", "en": "## The meeting point of talent and experience\n\nThe rapid development of technology enables the emergence of many new materials and indications. Despite all these developments, no other material has reached the level of aesthetics and function achieved with porcelain-coated prostheses. Porcelain-coated prostheses, which are produced with a labor-intensive process, manage to maintain their place with their indispensable aesthetic features in this period when the share of technology in production is increasing day by day.\n\nIn quality porcelain applications, the share of dental technicians who have worked on countless cases for many years, improving themselves step by step and gaining experience cannot be ignored. MB Dental produces prostheses that reach the highest aesthetics without losing their function with its experienced technicians who have mastered every process step and can fully meet all customer expectations.", "fr": "## La rencontre du talent et de l''expérience\n\nLe développement rapide de la technologie permet l''émergence de nombreux nouveaux matériaux et de nouvelles indications. Malgré tous ces développements, aucun matériau n''a atteint le niveau d''esthétique et de fonction des prothèses revêtues de porcelaine. Les prothèses revêtues de porcelaine, qui sont produites selon un processus à forte intensité de main-d''œuvre, parviennent à conserver leur place grâce à leurs caractéristiques esthétiques indispensables à une époque où la part de la technologie dans la production augmente de jour en jour.\n\nDans les applications de porcelaine de qualité, la part des techniciens dentaires qui ont travaillé sur d''innombrables cas pendant de nombreuses années, s''améliorant petit à petit et acquérant de l''expérience, ne peut être ignorée. MB Dental produit des prothèses qui atteignent l''esthétique la plus élevée sans perdre leur fonction grâce à ses techniciens expérimentés qui maîtrisent chaque étape du processus et peuvent répondre pleinement à toutes les attentes des clients."}'::jsonb, '{}'::jsonb, 20),
  ('inlay-onlay', 'sabit', '{"tr": "Inlay ve onlay", "en": "Inlays and onlays", "fr": "Inlays et onlays"}'::jsonb, '{"tr": "Kompozit ve seramik; CNC ya da 3D baskı", "en": "Composite and ceramic; milled or 3D printed", "fr": "Composite et céramique ; usinés ou imprimés"}'::jsonb, '{"tr": "## 3 boyutlu tasarım\n\nDoğası gereği inlay ve onlay protezler kullanıldığı alana renk ve adaptasyon bakımından maksimum uyum gerektiren ürünlerdir. Bu uyumu yakalamak için çalışmalarımızı aralıksız olarak sürdürüyor ve hep daha iyisini hedefliyoruz.\n\n## Güvenilir malzemeler\n\nHem kompozit hem seramik yapılarda en kalliteli ve güvenilir malzemeleri kullanarak en iyi ürünü ortaya koyuyoruz.\n\n> \"Mum modelasyon ile devam eden üretimimizi, 3D tasarım ile destekleyerek artan üretim hacmimizi yenilikle buluşturuyoruz.\"\n\n## Alternatif yöntemler\n\nYaptığımız dijital tasarımları gerçekleştirmek için hem CNC makinelerde işlenebilir bloklar, hem de 3D print edilmiş döküm yapılabilir malzemeler kullanıyor, bu şekilde müşterilerimizin taleplerine en uygun yöntemi seçip, en kaliteli ürünü ortaya çıkarıyoruz.", "en": "## 3 dimensional design\n\nBy nature, inlay and onlay prostheses are products that require maximum harmony in terms of color and adaptation to the area where they are used. In order to achieve this harmony, we continue our work uninterruptedly and always aim for the better.\n\n## Reliable materials\n\nWe produce the best product by using the highest quality and reliable materials in both composite and ceramic structures.\n\n> \"By supporting our production, which continues with wax modeling, with 3D design, we bring our increasing production volume together with innovation.\"\n\n## Alternative methods\n\nIn order to realize the digital designs we make, we use both CNC machinable blocks and 3D printed castable materials, in this way, we choose the most suitable method for our customers'' demands and create the highest quality product.", "fr": "## Conception en 3 dimensions\n\nPar nature, les prothèses inlay et onlay sont des produits qui exigent une harmonie maximale en termes de couleur et d''adaptation à la zone où elles sont utilisées. Pour atteindre cette harmonie, nous poursuivons notre travail sans relâche et visons toujours l''amélioration.\n\n## Des matériaux fiables\n\nNous produisons le meilleur produit en utilisant des matériaux fiables et de la plus haute qualité, tant pour les structures composites que pour les structures céramiques.\n\n> « En soutenant notre production, qui se poursuit avec le modelage de la cire, par la conception en 3D, nous associons l''augmentation de notre volume de production à l''innovation. »\n\n## Méthodes alternatives\n\nPour réaliser les conceptions numériques que nous faisons, nous utilisons à la fois des blocs usinables par CNC et des matériaux moulables imprimés en 3D. De cette manière, nous choisissons la méthode la plus adaptée aux demandes de nos clients et créons un produit de la plus haute qualité."}'::jsonb, '{}'::jsonb, 30),
  ('implant', 'sabit', '{"tr": "İmplant üstü", "en": "Implant restorations", "fr": "Implantologie"}'::jsonb, '{"tr": "Premill parçadan kişiye özel abutment", "en": "Custom abutments from premill blanks", "fr": "Piliers sur mesure à partir de pièces premill"}'::jsonb, '{"tr": "## Premıll parçalar\n\nImplant parçaların ağızdaki pozisyonlar ve açılarındaki farklılıklar her implant abutment parçası için kişiye özel üretim yapılmasını gerektirmektedir. MB Dental hem müşterilerinden gelen hazır parçaların kişiselleştirilmesi, hem de kişiye özel yaptığı tasarımları üreterek bu alandaki ihtiyacı en iyi şekilde karşılamaktadır.\n\nMB Dental müşterilerinin talep ettiği implant tipi ve arayüzleri doğrultusunda 3 boyutlu tarama ve tasarımlarını yaptığı kişiselleştirilmiş implant abutment parçaları, premill parçalar kullanarak üretmektedir. Bu üretime özel olarak ayrılmış CNC tezgahlarında ikincil işçiliği minimum seviyeye indiren hassasiyete sahip abutment parçalar üretilmektedir. Bu hassasiyet üstyapı – abutment parça uyumunu en yüksek seviyeye çıkarmaktadır.", "en": "## Premill parts\n\nThe differences in the positions and angles of the implant parts in the mouth require customized production for each implant abutment part. MB Dental meets the need in this field in the best way by both customizing ready-made parts from its customers and producing customized designs.\n\nMB Dental produces personalized implant abutment parts, which are 3D scanned and designed in line with the implant type and interfaces requested by its customers, using premill parts. In CNC machines specially dedicated to this production, abutment parts are produced with precision that minimizes secondary labor. This precision maximizes the superstructure – abutment part compatibility.", "fr": "## Pièces de fraisage\n\nLes différences de position et d''angle des parties de l''implant dans la bouche nécessitent une production sur mesure pour chaque partie du pilier de l''implant. MB Dental répond au mieux aux besoins dans ce domaine en personnalisant les pièces prêtes à l''emploi de ses clients et en produisant des conceptions personnalisées.\n\nMB Dental fabrique des piliers d''implants personnalisés, qu''elle scanne en 3D et conçoit en fonction du type d''implant et des interfaces demandés par ses clients, à partir de pièces pré-fabriquées. Sur des machines à commande numérique spécialement dédiées à cette production, les piliers sont fabriqués avec une précision qui minimise la main-d''œuvre secondaire. Cette précision permet de maximiser la compatibilité entre la superstructure et la pièce de pilier."}'::jsonb, '{}'::jsonb, 40),
  ('freze-atasman', 'hareketli', '{"tr": "Freze ve ataşman", "en": "Telescopes and attachments", "fr": "Télescopes et attachements"}'::jsonb, '{"tr": "Primer ve sekonder yapılar dijital", "en": "Primary and secondary structures designed digitally", "fr": "Structures primaires et secondaires en CFAO"}'::jsonb, '{"tr": "## Parçaların kusursuz uyumu, yüksek tutuculuk\n\nMB Dental kullanıcı konforunu hedef alarak müşteri taleplerine en uygun frezeli/ataşmanlı protezleri üretir. Sabit protez üretiminin tamamını CAD/CAM imalat yöntemleri ile üreten MB Dental, bu yolla primer yapılarda da kalite standardını en yüksek seviyeye taşımayı başarmıştır. Son dönemde yaptığı iyileştirme ve yatırımlarla sekonder yapılarda da bu çalışmasını tamamlayıp tüm frezeli ve ataşmanlı protezleri bilgisayar ortamında tasarlayıp üretmektedir.\n\nKombine işlerde mükemmel proteze ulaşmak için fonksiyonel uyumun yanı sıra, farklı malzemeler arasındaki form ve renk uyumu vazgeçilmez ihtiyaçlardan biridir. MB Dental bu uyumu yakalamak için gerekli tecrübe ve disiplini ortaya koyacak insan gücüne ve malzeme / ekipman altyapısına sahiptir.\n\n## Siz planlayın biz gerçekleştirelim\n\nProtez kullanıcısının ihtiyacı ve şartlar doğrultusunda her hekim farklı vakalar için farklı çözümler üretir. MB Dental teknisyenleri bu farkları anlar ve kullanıcı konforunun yanında hekimin adaptasyon kolaylığını düşünerek, talebe en uygun protezi üretir. Hekimin hastanın ihtiyacını karşılayacağını öngördüğü tüm ataşman tipleri MB Dental teknisyenleri tarafından bilinir ve hassiyetle uygulanır.\n\n## Yüksek tutuculuk için\n\nTecrübeli MB Dental teknisyenleri ister CAD/CAM, ister konvansiyonel yöntemlerle üretilmiş olsun, tüm protezleri tutuculuk ve hasta konforunu en yüksek seviyeye taşıyacak şekilde birleştirirler. Freze ve ataşmanlı protezleri üretmek için farklı disiplinlerden en tecrübeli MB Dental teknisyenleri büyük bir koordinasyon içerisinde çalışarak mükemmel protezler ortaya çıkarırlar.", "en": "## Perfect fit of parts, high retention\n\nMB Dental Dental Prosthodontics Laboratory produces the most suitable milled/attachment prostheses for customer demands by targeting user comfort. MB Dental Dental Prosthesis Laboratory, which manufactures all fixed prosthesis production with CAD/CAM manufacturing methods, has succeeded in carrying the quality standard to the highest level in primary structures in this way. With the recent improvements and investments, it has completed this work in secondary structures and designs and manufactures all milled and attachment prostheses in computer environment.\n\nIn addition to functional harmony, form and color harmony between different materials is one of the indispensable requirements to achieve the perfect prosthesis in combined works. MB Dental Dental Prosthesis Laboratory has the manpower and material / equipment infrastructure to demonstrate the necessary experience and discipline to achieve this harmony.\n\n## You plan and we will realize it\n\nIn line with the needs and conditions of the prosthesis user, each physician produces different solutions for different cases. MB Dental Dental Prosthesis Laboratory technicians understand these differences and produce the most suitable prosthesis for the demand, considering the user comfort as well as the ease of adaptation of the physician. All types of attachments that the physician foresees will meet the needs of the patient are known and precisely applied by the technicians of MB Dental Dental Prosthesis Laboratory.\n\n## For high retention\n\nExperienced MB Dental Dental Prosthodontics Laboratory technicians combine all prostheses, whether CAD/CAM or conventionally fabricated, to maximize retention and patient comfort. The most experienced MB Dental Dental Prosthodontics Laboratory technicians from different disciplines work in great coordination to produce milled and attachment prostheses, resulting in perfect prostheses.", "fr": "## Harmonie parfaite des pièces, rétention élevée\n\nLe Laboratoire de Prothèse Dentaire MB Dental réalise les prothèses fraisées/attachées les plus adaptées aux demandes des clients en visant le confort de l''utilisateur. Le Laboratoire de Prothèse Dentaire MB Dental, qui réalise l''ensemble de sa production de prothèses fixes avec des méthodes de fabrication CAD / CAM, a réussi à porter ainsi le niveau de qualité au plus haut dans les structures primaires. Avec les améliorations et les investissements récents, il a complété ce travail dans les structures secondaires et conçoit et fabrique toutes les prothèses fraisées et les prothèses d''attachement dans un environnement informatique.\n\nOutre l''harmonie fonctionnelle, l''harmonie des formes et des couleurs entre les différents matériaux est l''une des conditions indispensables à la réalisation d''une prothèse parfaite dans les travaux combinés. Le laboratoire de prothèse dentaire MB Dental dispose de la main-d''œuvre et de l''infrastructure matérielle et d''équipement nécessaires pour faire preuve de l''expérience et de la discipline requises pour réaliser cette harmonie.\n\n## Vous planifiez et nous réalisons\n\nEn fonction des besoins et des conditions de l''utilisateur de la prothèse, chaque médecin produit des solutions différentes pour des cas différents. Les techniciens du laboratoire de prothèses dentaires MB Dental comprennent ces différences et produisent la prothèse la plus adaptée à la demande, en tenant compte du confort de l''utilisateur et de la facilité d''adaptation du médecin. Tous les types d''attachements qui, selon le médecin, répondront aux besoins du patient sont connus des techniciens du laboratoire de prothèses dentaires MB Dental et sont appliqués avec précision.\n\n## Pour une rétention élevée\n\nLes techniciens expérimentés du laboratoire de prothèse dentaire MB Dental combinent toutes les prothèses, qu''elles soient CAD/CAM ou conventionnelles, pour maximiser la rétention et le confort du patient. Les techniciens les plus expérimentés du laboratoire de prothèse dentaire MB Dental, issus de différentes disciplines, travaillent en grande coordination pour produire des prothèses fraisées et des prothèses d''attachement, ce qui permet d''obtenir des prothèses parfaites."}'::jsonb, '{}'::jsonb, 50),
  ('akrilik-protez', 'hareketli', '{"tr": "Akrilik ve flexite", "en": "Acrylic and flexible", "fr": "Résine et flexible"}'::jsonb, '{"tr": "Parsiyel, total, esnek protez", "en": "Partial, complete, flexible dentures", "fr": "Partielle, complète, flexible"}'::jsonb, '{"tr": "## Hız, kalite ve konfor bir arada\n\nKullanıcıları eski konforuna kavuşturmanın en hızlı yolu akrilik protezlerdir. Parsiyel ya da total tüm akrilik protezler, kullanıcı konforu düşünülerek ve hekimin planlamasına en uygun şekilde üretilir. Esnek malzemeler kullanılarak üretilen flexite protezler hastaya büyük konfor sağlarken, sert malzemeler dayanıklılığı ve uygun maliyeti nedeniyle tercih sebebi olmaktadır.\n\n## Yetenekli eller, kaliteli malzeme ile buluşuyor\n\nFrezeli, ataşmanlı, iskeletli, parsiyel ya da total tüm klasik protezler usta MB Dental teknisyenlerinin ellerinden çıkmaktadır. Her adımda tecrübesini kanıtlamış teknisyenler, uygun renk ve forma sahip en kaliteli malzemeleri kullanarak estetik ve konfor açısından en iyi protezi ortaya çıkarmak için çalışırlar. Özellikle kombine protezler gibi yüksek uyum ve koordinasyona ihtiyaç duyan protez tiplerinde estetik detaylar ön planda tutularak primer aşamadan bitmiş proteze ulaşana kadar tüm işlemler tek tek planlanır ve takip edilir.", "en": "## Fast, quality and comfort in one\n\nAcrylic prostheses are the fastest way to restore users to their former comfort. All acrylic prostheses, partial or total, are produced with the comfort of the user in mind and in the most suitable way for the physician''s planning. Flexite prostheses produced using flexible materials provide great comfort to the patient, while rigid materials are preferred due to their durability and affordable cost.\n\n## Skilled hands meet quality materials\n\nAll classic prostheses, whether milled, with attachments, skeletal, partial or total, come from the hands of skilled MB Dental technicians. At every step, experienced technicians work to create the best prosthesis in terms of aesthetics and comfort, using the highest quality materials with the appropriate color and shape. Especially in prosthesis types that require high harmony and coordination, such as combined prostheses, aesthetic details are prioritized and all processes are planned and followed individually from the primary stage to the finished prosthesis.", "fr": "## Rapidité, qualité et confort en un\n\nLe moyen le plus rapide de redonner à l''utilisateur son confort d''antan est la prothèse acrylique. Toutes les prothèses acryliques, partielles ou totales, sont fabriquées en tenant compte du confort de l''utilisateur et de la manière la plus adaptée à la planification du médecin. Les prothèses Flexite produites avec des matériaux flexibles offrent un grand confort au patient, tandis que les matériaux durs sont préférés en raison de leur durabilité et de leur coût abordable.\n\n## Des mains expertes pour des matériaux de qualité\n\nToutes les prothèses classiques avec fraises, attachements, armatures, partielles ou totales sont réalisées par des techniciens qualifiés de MB Dental. A chaque étape, des techniciens expérimentés travaillent pour créer la meilleure prothèse en termes d''esthétique et de confort, en utilisant des matériaux de la plus haute qualité avec la couleur et la forme appropriées. En particulier pour les types de prothèses qui exigent une grande harmonie et une bonne coordination, comme les prothèses combinées, les détails esthétiques sont prioritaires et tous les processus sont planifiés et suivis individuellement depuis le stade primaire jusqu''à la prothèse finie."}'::jsonb, '{}'::jsonb, 60),
  ('iskelet', 'hareketli', '{"tr": "İskelet", "en": "Partial frameworks", "fr": "Stellites"}'::jsonb, '{"tr": "Döküm ve CAD/CAM", "en": "Cast and CAD/CAM", "fr": "Coulée et CFAO"}'::jsonb, '{"tr": "## Eski ve yeni bir arada\n\nMB Dental konvansiyonel döküm yönteminin yanında iskelet altyapılarda da CAD/CAM üretim yöntemini uygulamaya almayı başarmıştır. Bu yöntemle tasarımını ve üretimini yaptığı protezlerin oranını artırmak üzerine çalışmalarını sürdürmektedir. Hem 3D Print yöntemi ile döküm sürecine girdi sağlama, hem de lazer sinter ile direkt bitmiş iskelete ulaşma alternatiflerini değerlendirmekte, bu doğrultuda istenen kaliteye en uygun yöntemi belirlemek üzere çalışmalarını devam ettirmektedir.\n\n## Detayları farkedin\n\nİskelet altyapılarda tutuculuğu sağlamak için yapılması gereken en ince detayları görmek ve bu detaylara uyumlu planlamayı ve tasarımı ortaya koymaktır.", "en": "## Old and new together\n\nMB Dental has succeeded in implementing the CAD/CAM production method in skeletal infrastructures as well as the conventional casting method. It continues to work on increasing the rate of prostheses designed and manufactured with this method. It is evaluating both the alternatives of providing input to the casting process with the 3D Print method and directly reaching the finished skeleton with laser sinter, and continues to work to determine the most suitable method for the desired quality in this direction.\n\n## Notice the details\n\nIn order to ensure retention in skeletal infrastructures, it is necessary to see the finest details and to put forward the planning and design in accordance with these details.", "fr": "## L''ancien et le nouveau ensemble\n\nMB Dental a réussi à mettre en œuvre la méthode de production CAD/CAM dans les infrastructures squelettiques au même titre que la méthode de coulée conventionnelle. Elle continue à travailler sur l''augmentation du taux de prothèses conçues et fabriquées avec cette méthode. Il évalue à la fois les alternatives consistant à alimenter le processus de moulage avec la méthode d''impression 3D et à atteindre directement le squelette fini avec le frittage laser, et continue à travailler pour déterminer la méthode la plus appropriée pour la qualité souhaitée dans cette direction.\n\n## Attention aux détails\n\nAfin de garantir le maintien des infrastructures squelettiques, il est nécessaire de voir les détails les plus fins et de proposer une planification et une conception conformes à ces détails."}'::jsonb, '{}'::jsonb, 70),
  ('ortodonti', 'ortodonti', '{"tr": "Plaklar ve apareyler", "en": "Plates and appliances", "fr": "Plaques et appareils"}'::jsonb, '{"tr": "Yükseltme ve düzeltme plaklarında uzmanlık", "en": "Specialised in expansion and correction plates", "fr": "Spécialistes des plaques d''expansion et de correction"}'::jsonb, '{"tr": "## Gülümsemenizi yeniden keşfedin\n\nGenel diş protez uygulamalarında, kaybedilen dişlerin yerini alacak protezlerin üretilmesi hedeflenir. Bunun yanı sıra, ortodontik tedaviler diş ve çene pozisyonlarındaki ya da fonksiyonlarındaki kayıpları önlemeyi ve/veya düzeltmeyi amaçlar.\n\n## Gülüşünüzde yeni bir dönem\n\nDiğer diş protez laboratuvarlarından farklı olarak MB Dental, ortodontik uygulamaları ayrı bir üretim bölümü çatısı altında tutarak bu ürünlere verdiği önemi en iyi şekilde ortaya koymaktadır. MB Dental, müşterilerinden gelen ortodontik aparey taleplerini ortodonti başlığı altında topladığı geniş ürün portföyü ile karşılamaktadır. Müşterilerinden gelen farklı talepleri değerlendiren MB Dental, her geçen gün bu alandaki yeteneklerini geliştirmekte ve ürün portföyünü artırmaktadır. Özellikle yükseltme/düzeltme plaklarının planlanması ve üretimi konusunda uzmanlaşan MB Dental ortodonti ekibi, kullanıcıları adım adım daha güzel bir gülümsemeye ulaştırmak için gereken çabayı göstermektedir.", "en": "## Rediscover your smile\n\nIn general dental prosthodontic applications, it is aimed to produce prostheses to replace lost teeth. In addition, orthodontic treatments aim to prevent and/or correct losses in tooth and jaw positions or functions.\n\n## A new era in your smile\n\nUnlike other dental prosthodontic laboratories, MB Dental keeps orthodontic applications under the roof of a separate production department, demonstrating the importance it attaches to these products in the best way. MB Dental meets the orthodontic appliance demands of its customers with its wide product portfolio under the title of orthodontics. Evaluating the different demands of its customers, MB Dental improves its capabilities in this field and increases its product portfolio day by day. MB Dental orthodontics team, which specializes especially in the planning and production of elevation / correction plates, makes the necessary efforts to bring users to a more beautiful smile step by step.", "fr": "## Redécouvrez votre sourire\n\nDans les applications générales de prothèse dentaire, il s''agit de produire des prothèses pour remplacer les dents perdues. En outre, les traitements orthodontiques visent à prévenir et/ou à corriger les pertes de position ou de fonction des dents et des mâchoires.\n\n## Une nouvelle ère pour votre sourire\n\nContrairement à d''autres laboratoires de prothèses dentaires, MB Dental, en gardant les applications orthodontiques sous le toit d''un département de production séparé, démontre de la meilleure façon l''importance qu''il accorde à ces produits. MB Dental répond aux demandes d''appareils orthodontiques de ses clients grâce à son large portefeuille de produits sous le titre d''orthodontie. MB Dental, qui évalue les différentes demandes de ses clients, améliore chaque jour ses capacités dans ce domaine et élargit son portefeuille de produits. L''équipe d''orthodontie de MB Dental, spécialisée dans la planification et la production de plaques d''élévation et de correction, déploie tous les efforts nécessaires pour permettre aux utilisateurs d''avoir un plus beau sourire, étape par étape."}'::jsonb, '{"tr": "Geniş Ürün Seçenekleri\nVerimli Planlama\nÖzelleştirilmiş Çözümler\nKaliteli Malzeme", "en": "Wide Range of Product Options\nEfficient Planning\nCustomized Solutions\nQuality Material", "fr": "Large gamme d''options de produits\nUne planification efficace\nSolutions personnalisées\nMatériau de qualité"}'::jsonb, 80)
